=== flagd-config ===
{"demo.flagd.json":"{
  "$schema": "https://flagd.dev/schema/v0/flags.json",
  "flags": {
    "llmInaccurateResponse": {
      "defaultVariant": "off",
      "description": "LLM returns an inaccurate product summary for product ID L9ECAV7KIM",
      "state": "ENABLED",
      "variants": {
        "off": false,
        "on": true
      }
    },
    "llmRateLimitError": {
      "defaultVariant": "off",
      "description": "LLM intermittently returns a rate limit error",
      "state": "ENABLED",
      "variants": {
        "off": false,
        "on": true
      }
    },
    "productCatalogFailure": {
      "description": "Fail product catalog service on a specific product",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "recommendationCacheFailure": {
      "description": "Fail recommendation service cache",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "adManualGc": {
      "description": "Triggers full manual garbage collections in the ad service",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "adHighCpu": {
      "description": "Triggers high cpu load in the ad service",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "adFailure": {
      "description": "Fail ad service",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "kafkaQueueProblems": {
      "description": "Overloads Kafka queue while simultaneously introducing a consumer side delay leading to a lag spike",
      "state": "ENABLED",
      "variants": {
        "on": 100,
        "off": 0
      },
      "defaultVariant": "off"
    },
    "cartFailure": {
      "description": "Fail cart service",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "paymentFailure": {
      "description": "Fail payment service charge requests n%",
      "state": "ENABLED",
      "variants": {
        "100%": 1,
        "90%": 0.95,
        "75%": 0.75,
        "50%": 0.5,
        "25%": 0.25,
        "10%": 0.1,
        "off": 0
      },
      "defaultVariant": "off"
    },
    "paymentUnreachable": {
      "description": "Payment service is unavailable",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "loadGeneratorFloodHomepage": {
      "description": "Flood the frontend with a large amount of requests.",
      "state": "ENABLED",
      "variants": {
        "on": 100,
        "off": 0
      },
      "defaultVariant": "off"
    },
    "imageSlowLoad": {
      "description": "slow loading images in the frontend",
      "state": "ENABLED",
      "variants": {
        "10sec": 10000,
        "5sec": 5000,
        "off": 0
      },
      "defaultVariant": "off"
    },
    "failedReadinessProbe": {
      "description": "readiness probe failure for cart service",
      "state": "ENABLED",
      "variants": {
        "on": true,
        "off": false
      },
      "defaultVariant": "off"
    },
    "emailMemoryLeak": {
      "description": "Memory leak in the email service.",
      "state": "ENABLED",
      "variants": {
        "off": 0,
        "1x": 1,
        "10x": 10,
        "100x": 100,
        "1000x": 1000,
        "10000x": 10000
      },
      "defaultVariant": "off"
    }
  }
}
"}
=== flagd deploy args ===

action:
export KUBECONFIG=/root/.kube/config.fixed; kubectl run dbg --rm -i --restart=Never -n astronomy-shop --image=curlimages/curl:8.10.1 -- sh -c "curl -s -o /dev/null -w 'frontend-proxy:%{http_code}
' --max-time 10 http://frontend-proxy:8080/; curl -s -o /dev/null -w 'frontend:%{http_code}
' --max-time 10 http://frontend:8080/; curl -s -o /dev/null -w 'product-catalog:%{http_code}
' --max-time 10 http://product-catalog:8080/products; curl -s --max-time 10 http://product-catalog:8080/products | head -c 300" 2>&1 | tail -20

